def roman_to_integer(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = values[ch]
        if v < prev:
            total -= v
        else:
            total += v
        prev = v
    return total

def majority_element(nums):
    candidate = None
    count = 0
    for x in nums:
        if count == 0:
            candidate = x
            count = 1
        elif x == candidate:
            count += 1
        else:
            count -= 1
    return candidate

def power_of_three(n):
    if n <= 0:
        return False
    while n % 3 == 0:
        n //= 3
    return n == 1

def excel_sheet_column_title(column):
    res = []
    while column > 0:
        column -= 1
        res.append(chr(ord('A') + column % 26))
        column //= 26
    return ''.join(reversed(res))

def hamming_weight(n):
    cnt = 0
    while n > 0:
        cnt += n & 1
        n >>= 1
    return cnt

def rotate_array(nums, k):
    n = len(nums)
    if n == 0:
        return []
    k = k % n
    return nums[n - k:] + nums[:n - k]

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    res = [list(intervals[0])]
    for i in range(1, len(intervals)):
        s, e = intervals[i]
        if s <= res[-1][1]:
            if e > res[-1][1]:
                res[-1][1] = e
        else:
            res.append([s, e])
    return res

def multiply_strings(num1, num2):
    if num1 == '0' or num2 == '0':
        return '0'
    n1 = len(num1)
    n2 = len(num2)
    res = [0] * (n1 + n2)
    for i in range(n1 - 1, -1, -1):
        a = ord(num1[i]) - 48
        for j in range(n2 - 1, -1, -1):
            b = ord(num2[j]) - 48
            pos = i + j + 1
            cur = res[pos] + a * b
            res[pos] = cur % 10
            res[pos - 1] += cur // 10
    start = 0
    while start < len(res) - 1 and res[start] == 0:
        start += 1
    return ''.join(str(d) for d in res[start:])

def min_subarray_len(target, nums):
    left = 0
    total = 0
    best = len(nums) + 1
    for right in range(len(nums)):
        total += nums[right]
        while total >= target:
            cur = right - left + 1
            if cur < best:
                best = cur
            total -= nums[left]
            left += 1
    return 0 if best == len(nums) + 1 else best

def two_sum_ii(numbers, target):
    lo = 0
    hi = len(numbers) - 1
    while lo < hi:
        s = numbers[lo] + numbers[hi]
        if s == target:
            return [lo + 1, hi + 1]
        if s < target:
            lo += 1
        else:
            hi -= 1
    return []

def daily_temperatures(temperatures):
    n = len(temperatures)
    res = [0] * n
    stack = []
    for i in range(n):
        while stack and temperatures[i] > temperatures[stack[-1]]:
            j = stack.pop()
            res[j] = i - j
        stack.append(i)
    return res

def decode_string(s):
    num_stack = []
    str_stack = []
    cur = ''
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + ord(ch) - 48
        elif ch == '[':
            num_stack.append(num)
            str_stack.append(cur)
            cur = ''
            num = 0
        elif ch == ']':
            prev = str_stack.pop()
            k = num_stack.pop()
            cur = prev + cur * k
        else:
            cur += ch
    return cur

def first_missing_positive(nums):
    n = len(nums)
    i = 0
    while i < n:
        x = nums[i]
        if 1 <= x <= n and nums[x - 1] != x:
            nums[x - 1], nums[i] = nums[i], nums[x - 1]
        else:
            i += 1
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

def trapping_rain_water(height):
    n = len(height)
    left = 0
    right = n - 1
    left_max = 0
    right_max = 0
    water = 0
    while left < right:
        if height[left] < height[right]:
            if height[left] >= left_max:
                left_max = height[left]
            else:
                water += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]
            else:
                water += right_max - height[right]
            right -= 1
    return water

def minimum_window_substring(s, t):
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    missing = len(t)
    left = 0
    best = ''
    best_len = len(s) + 1
    for right in range(len(s)):
        ch = s[right]
        if ch in need:
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1
        while missing == 0:
            cur = right - left + 1
            if cur < best_len:
                best_len = cur
                best = s[left:right + 1]
            lch = s[left]
            if lch in need:
                need[lch] += 1
                if need[lch] > 0:
                    missing += 1
            left += 1
    return best

def candy(ratings):
    n = len(ratings)
    candies = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1] and candies[i] <= candies[i + 1]:
            candies[i] = candies[i + 1] + 1
    return sum(candies)

def split_array_largest_sum(nums, k):
    def can_split(limit):
        cnt = 1
        cur = 0
        for x in nums:
            if cur + x > limit:
                cnt += 1
                cur = x
            else:
                cur += x
        return cnt <= k
    lo = max(nums)
    hi = sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_split(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
